@register.simple_tag
def sf_icon(name, extra_class=''):
    """Render Apple SF Symbol SVG."""
    template_str = ICONS.get(name, ICONS.get('target'))
    classes = f"sf-icon {extra_class}".strip()
    return mark_safe(template_str.format(classes=classes))


@register.simple_tag
def category_sf_icon(cat_name, extra_class=''):
    """Return matching Apple SF symbol based on category name."""
    name_lower = (cat_name or '').lower()
    if any(k in name_lower for k in ['work', 'career', 'code', 'build']):
        return sf_icon('briefcase', extra_class)
    elif any(k in name_lower for k in ['health', 'workout', 'fitness', 'run', 'gym', 'sport']):
        return sf_icon('figure_run', extra_class)
    elif any(k in name_lower for k in ['learn', 'read', 'study', 'book']):
        return sf_icon('book', extra_class)
    elif any(k in name_lower for k in ['mind', 'meditat', 'zen', 'calm', 'peace']):
        return sf_icon('leaf', extra_class)
    elif any(k in name_lower for k in ['sleep', 'rest', 'recovery', 'nap']):
        return sf_icon('moon_stars', extra_class)
    elif any(k in name_lower for k in ['social', 'family', 'friend']):
        return sf_icon('people', extra_class)
    elif any(k in name_lower for k in ['leisure', 'game', 'play', 'movie']):
        return sf_icon('game', extra_class)
    elif any(k in name_lower for k in ['chore', 'errand', 'clean']):
        return sf_icon('checklist', extra_class)
    elif any(k in name_lower for k in ['meal', 'food', 'eat', 'nutrit']):
        return sf_icon('fork_knife', extra_class)
    else:
        return sf_icon('target', extra_class)
